class METRunBaseBatchMultiThreadBase extends RunBaseBatch
{
    str                             batchIdentifier;
    BatchHeader                     batchHeader;
    METRunBaseBatchMultiThreadBase  finalTask;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        batchIdentifier
    #endmacro
}

Method.Source:
public void run()
{
    container batchIdentifierCon;
    int       i;

    if (batchIdentifier)
    {
        if (batchIdentifier == this.finalTaskIdentifier())
        {
            this.runFinalTask();
        }
        else
        {
            this.runThreadTask();
        }
    }
    else
    {
        this.runStartTask();

        batchIdentifier = this.finalTaskIdentifier();
        this.processThreadItem(true); // final task created first so children can depend on it

        batchIdentifierCon = this.getBatchIdentifiersRangeCon();

        for (i = 1; i <= conLen(batchIdentifierCon); i++)
        {
            batchIdentifier = conPeek(batchIdentifierCon, i);
            this.processThreadItem(false);
        }

        if (finalTask)
        {
            if (this.isInBatch())
            {
                batchHeader.save();
            }
            else
            {
                finalTask.run();
            }
        }
    }
}

protected void processThreadItem(boolean _isFinalTask)
{
    METRunBaseBatchMultiThreadBase childThread;

    childThread = RunBase::makeObject(classIdGet(this));
    childThread.batchInfo().resetBatchHeader();
    childThread.batchInfo().parmGroupId(this.parmCurrentBatch().GroupId);
    childThread.batchInfo().parmConstraintType(BatchConstraintType::And);
    childThread.batchInfo().parmDataareaId(this.parmCurrentBatch().Company);
    childThread.unpack(this.pack());

    if (_isFinalTask)
    {
        finalTask = childThread;
    }

    if (this.isInBatch())
    {
        if (!batchHeader)
        {
            batchHeader = BatchHeader::construct(this.parmCurrentBatch().BatchJobId);
        }
        batchHeader.addRuntimeTask(childThread, this.parmCurrentBatch().RecId);

        if (!_isFinalTask && finalTask)
        {
            batchHeader.addDependency(finalTask, childThread);
        }
    }
    else if (!_isFinalTask)
    {
        childThread.run();
    }
}

public boolean unpack(container _packedClass)
{
    Version version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            break;
        default:
            return false;
    }
    return true;
}

public str parmBatchIdentifier(str _batchIdentifier = batchIdentifier)
{
    batchIdentifier = _batchIdentifier;
    return batchIdentifier;
}
